UPDATE question_record
SET answer = #{answer}, is_correct = #{isCorrect}, is_answered = #{isAnswered}, do_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT qr.*, q.id as q_id, q.book_id as q_book_id, q.type_id as q_type_id, q.content as q_content, q.options as q_options, q.answer as q_answer, q.analysis as q_analysis, q.difficulty as q_difficulty, qt.type_name as q_type_name, (SELECT COUNT(*) FROM question_record qr2 WHERE qr2.question_id = qr.question_id AND qr2.user_id = qr.user_id AND qr2.is_correct = 0) as error_count FROM question_record qr LEFT JOIN question q ON qr.question_id = q.id LEFT JOIN question_type qt ON q.type_id = qt.id WHERE qr.id IN ( SELECT MAX(id) FROM question_record WHERE user_id = #{userId} AND is_correct = 0
AND book_id = #{bookId}
AND question_id IN (SELECT id FROM question WHERE type_id = #{typeId})
GROUP BY question_id )
AND q.type_id = #{typeId}
ORDER BY qr.do_time DESC

SELECT COUNT(DISTINCT qr.question_id)
FROM question_record qr
LEFT JOIN question q ON qr.question_id = q.id
WHERE qr.user_id = #{userId} AND qr.is_correct = 0

    AND qr.book_id = #{bookId}


    AND q.type_id = #{typeId}
